#![allow(clippy::redundant_field_names)] // false positives in darling macro

use darling::{FromDeriveInput, FromVariant, ast::Fields};
use proc_macro2::{Span, TokenStream};
use quote::quote;
use syn::{Ident, spanned::Spanned};

use crate::util::GetDocs;

/// Name of the module generated by the [`Message`] macro which contains the
/// message enum variant type aliases
pub const MESSAGE_META_TYPES_IDENT: &str = "__message_meta_types";

#[derive(FromVariant)]
#[darling(forward_attrs(doc))]
struct MessageVariant {
    ident: Ident,
    fields: Fields<syn::Field>,
    attrs: Vec<syn::Attribute>,
}

fn parse_path_list(meta: &syn::Meta) -> darling::Result<Vec<syn::Path>> {
    if let syn::Meta::NameValue(value) = meta
        && let syn::Expr::Array(arr) = &value.value
    {
        let paths = arr
            .elems
            .iter()
            .map(|expr| {
                if let syn::Expr::Path(syn::ExprPath { path, .. }) = expr {
                    Ok(path.clone())
                } else {
                    Err(darling::Error::custom("Expected path").with_span(&expr.span()))
                }
            })
            .collect::<darling::Result<Vec<_>>>()?;
        return Ok(paths);
    }

    Err(darling::Error::custom(
        "Expected named attribute #[message(struct_derives = [...])]",
    ))
}

#[derive(FromDeriveInput)]
#[darling(supports(enum_any), attributes(message))]
pub struct Message {
    data: darling::ast::Data<MessageVariant, ()>,

    /// Optional derives which are added for the struct variant type aliases.
    ///
    /// **Important**: You can specify this attribute multiple times. All derive paths will
    /// be merged and duplicate paths get removed.
    ///
    /// # Usage
    /// ```rust,ignore
    /// #[derive(Message, Clone)]
    /// #[message(struct_derives = [Debug])]
    /// #[message(struct_derives = [Clone])]
    /// enum Message { ... }
    /// ```
    #[darling(multiple, with = "parse_path_list", rename = "struct_derives")]
    derives: Vec<Vec<syn::Path>>,
}

pub fn handle(message: Message) -> TokenStream {
    let variants = message.data.take_enum().unwrap_or_default();

    let mut derives = Vec::<syn::Path>::new();
    message
        .derives
        .into_iter()
        .flatten()
        .for_each(|derive_path| {
            if !derives.contains(&derive_path) {
                derives.push(derive_path);
            }
        });

    let meta_types_mod = Ident::new(MESSAGE_META_TYPES_IDENT, Span::call_site());
    let meta_types = meta_types(&variants, &derives);

    quote! {
        /// generated by [`data_macros::Message`] macro
        pub mod #meta_types_mod {
            #[allow(clippy::wildcard_imports)] // this is such that in most cases, the types are found
            use super::*;

            #meta_types
        }
    }
}

/// Generate the type aliases for all message variants
///
/// Note that for non-newtype variants the type aliases are created like this
/// - If the variant is a struct type, then instead of a type alias a new struct with
///   all fields of the variant is created \
///   **Important**: All fields of the struct need to implement [`bincode::Encode`] and [`bincode::Decode`]
///   as the new struct derives those traits
/// - If the variant is a tuple type (with more than one type), then instead of a type alias
///   a new tuple with all fields of the variant is created \
///   **Important**: All fields of the tuple need to implement [`bincode::Encode`] and [`bincode::Decode`]
///   as the tuple type won't be encodable/decodable otherwise
fn meta_types(variants: &[MessageVariant], struct_derives: &[syn::Path]) -> TokenStream {
    /// A helper function to check if `ident` would alias `ty`. Then we inject `super::`.
    fn does_alias(ident: &Ident, ty: &syn::Type) -> bool {
        if let syn::Type::Path(type_path) = ty {
            // Check if the path is simple (e.g., "X", not "std::vec::Vec")
            // and has no extra punctuation or generic arguments.
            if type_path.qself.is_none() && type_path.path.segments.len() == 1 {
                let segment = &type_path.path.segments[0];
                return segment.ident == *ident && segment.arguments.is_empty();
            }
        }
        false
    }

    let derive_tokens = if struct_derives.is_empty() {
        quote! {}
    } else {
        quote! {
          #[derive(#(#struct_derives,)*)]
        }
    };

    let (type_defs, docs) = variants
        .iter()
        .map(|variant| {
            let (types, type_idents) = variant
                .fields
                .iter()
                .map(|field| (&field.ty, &field.ident))
                .collect::<(Vec<_>, Vec<_>)>();

            let ident = &variant.ident;

            let type_def = if variant.fields.is_struct() {
                // if the variant is a struct type, we create a new struct with the same fields
                // instead of a type alias
                quote! {
                    #derive_tokens
                    pub struct #ident {
                        #(pub #type_idents: #types),*
                    }
                }
            } else if variant.fields.is_unit() {
                quote! { pub type #ident = (); }
            } else if variant.fields.is_newtype()
                && let Some(field_type) = types.first()
            {
                if does_alias(ident, field_type) {
                    quote! { pub type #ident = super::#field_type; }
                } else {
                    quote! { pub type #ident = #field_type; }
                }
            } else {
                // if the variant is a tuple type with more than one type, we create a new
                // tuple with the same fields instead of a type alias
                quote! { pub type #ident = (#(#types),*); }
            };

            (type_def, variant.attrs.get_docs())
        })
        .collect::<(Vec<_>, Vec<_>)>();

    quote! {
        #(
            #docs
            #type_defs
        )*
    }
}
